#include "project_pool.hpp"
static void projectPoolTests(){
    Project p;p.tracks.resize(2);auto&t=p.tracks[0];t.name="Lead";t.patternName="Intro";t.notes={{0,.5,60,.9f}};t.patternLength=4;t.patterns={{"Chorus",8,{{1,.5,72,.8f}}}};p.tracks[1].name="Bass";auto sample=std::make_shared<Sample>();sample->rate=48000;sample->path=L"C:/Project/Kick.wav";sample->left.resize(48000);sample->right.resize(48000);t.sample=sample;t.clips={{0,4}};t.clips[0].audio=sample;p.tracks[1].clips={{4,4}};p.tracks[1].clips[0].audio=sample;
    auto patterns=projectPoolItems(p,false);check(patterns.size()==3&&patterns[1].pattern==1&&patterns[1].name==L"Chorus","Project Pool lists every track pattern");check(projectPoolItems(p,false,L"CHORUS").size()==1&&projectPoolItems(p,false,L"lead").size()==2,"Project Pool search matches names and channels without case sensitivity");auto audio=projectPoolItems(p,true);check(audio.size()==1&&audio[0].audio==sample,"Project Pool audio deduplicates samples shared by clips and tracks");
    check(projectPoolItems(p,true,L"bass").size()==1,"audio search finds a shared file on any matching channel");
    int at=placePoolItem(p,patterns[1],0,12);check(p.tracks[0].clips[at].pattern==1&&p.tracks[0].clips[at].beat==12&&p.tracks[0].clips[at].length==8,"pool pattern placement retains its pattern identity and timing");at=placePoolItem(p,patterns[1],1,0);check(p.tracks[1].patterns.size()==1&&p.tracks[1].patterns[0].notes[0].pitch==72,"dropping a pattern on another channel copies editable notes");at=placePoolItem(p,audio[0],1,24);check(p.tracks[1].clips[at].audio==sample&&std::abs(p.tracks[1].clips[at].length-p.bpm/60.)<1e-6,"audio pool creates a clip using the loaded source without disk decoding");
    auto withoutAudio=p;for(auto&track:withoutAudio.tracks){track.sample.reset();for(auto&clip:track.clips)clip.audio.reset();}auto saved=projectFromJson(projectJson(withoutAudio,L"work/test-results/Pool.vamp"),L"work/test-results/Pool.vamp");check(saved.tracks[1].patterns.size()==1,"patterns copied from Pool persist in projects");
    auto all=projectPoolItems(p,false);auto byLength=all;sortPoolItems(byLength,p,2,true);check(byLength.front().length==8,"pool length sorting works numerically");auto audioAfter=projectPoolItems(p,true);check(audioAfter[0].uses==3&&poolOccurrences(p,audioAfter[0]).size()==3,"shared audio placement count matches clips across tracks");
    auto sequence=p;auto seq=placePoolItems(sequence,{all[0],all[1]},0,40,false);check(seq.size()==2&&sequence.tracks[0].clips[seq[1].second].beat==44,"batch sequence uses consecutive positions");auto layers=p;auto layered=placePoolItems(layers,{all[0],all[1]},1,40,true);check(layers.tracks.size()==3&&layered[1].first==2&&layers.tracks[2].clips.back().beat==40,"layer placement appends tracks while keeping aligned positions");auto frozen=p;frozen.tracks[0].frozen=true;bool rejected=false;try{placePoolItems(frozen,{all[0]},0,0,false);}catch(...){rejected=true;}check(rejected,"pool rejects editing a frozen destination");
    auto full=p;full.tracks.resize(TrackCount);rejected=false;try{placePoolItems(full,{all[0],all[1]},TrackCount-1,0,true);}catch(...){rejected=true;}check(rejected,"layer placement obeys the track limit");
    std::ofstream(L"work/test-results/project-pool.json")<<Json({{"passed",true},{"all_patterns",true},{"deduplicated_audio",true},{"search",true},{"batch_sequence_and_layers",true},{"sort_and_placement_count",true},{"frozen_and_track_limits",true}}).dump(2);
}
